-- Dosya: QuestTranslator_GossipData.lua
-- Sadece Gossip (Sohbet) çevirilerini içerir

QuestTranslator_GossipData = {
    ["I know, I know, I'm out here in the middle of nowhere!\n\nMy home is actually in Ratchet, but after crashing my zeppelin here, I thought I might as well start the research I came here to do!"] = "Biliyorum, biliyorum, kuş uçmaz kervan geçmez bir yerdeyim!\n\nEvim aslında Dişliçark'ta, ama zeplinimi buraya düşürdükten sonra, buraya yapmaya geldiğim araştırmaya başlamanın iyi bir fikir olabileceğini düşündüm!",
    ["Ah a visitor! Must be an adventurer, we don't get many tourists down this way. Grab a chair and a drink, make yourself comfortable. Say, you look like you have some meat on your bones. You thinkin about competing in the cage matches?"] = "Ah, bir ziyaretçi! Bir maceracı olmalı, buralara pek turist uğramaz. Bir sandalye çek, bir şeyler iç ve rahatına bak. Cılız da değilsin hani. Kafes dövüşlerinde yarışmayı düşünür müsün?",
    ["It's a miracle I made it here in one piece, buddy. I'm tellin' ya, the desert is out to get ya, ALL THE TIME!"] = "Tek parça hâlinde buraya gelebilmem adeta bir mucize, dostum. Sana söylüyorum, çöl seni yok etmek için can atıyor, HER AN!",
    ["We may have been suffering a drought but there's no shortage of meat! Care to browse my goods?"] = "Kuraklık çekiyor olabiliriz ama et kıtlığı yaşadığımız söylenemez! Mallarıma göz atmak ister misin?",
    ["Living out here in the desert is rough! I get so thirsty standing outside in this heat."] = "Çölün ortasında yaşamak çok zor! Bu sıcakta dışarıda dikilmekten içim kuruyor.",
    ["Welcome to Tanaris, YOUR_NAME. How can I be of service to you today? You don't look like a blacksmith to me, but I know how looks can be deceiving."] = "Tanaris'e hoş geldin, YOUR_NAME. Bugün sana nasıl yardımcı olabilirim? Bana pek demirci gibi görünmüyorsun, ama dış görünüşün nasıl aldatıcı olabileceğini iyi bilirim.",
    ["Sul'thraze... the first time I heard the word uttered I was around your age. It meant nothing to me then, as it means nothing to you now. It was not until a warband of trolls coming from Zul'Farrak laid waste to the land that I understood... and feared.\n\nMany will tell you that the Splitblade of Suffering does not exist. That it's a myth; a rumor started to scare children 'straight.' But believe me, YOUR_RACE, it exists.\n\n<Trenton loses focus as he runs his hand across the jagged scar on his face.>"] = "Sul'thraze... Bu kelimeyi ilk duyduğumda senin yaşlarındaydın. O zamanlar benim için ne ifade ediyorsa, şu an senin için de hiçbir şey ifade etmiyor. Zul'Farrak'tan gelen bir trol savaş birliği toprakları kasıp kavurana kadar anlamamıştım... ve korkmamıştım.\n\nBirçoğu sana Acının Bölünmüş Kılıcı'nın var olmadığını söyleyecektir. Bunun bir efsane olduğunu; çocukları korkutup yola getirmek için çıkarılmış bir söylenti olduğunu. Ama bana inan, YOUR_RACE, o var.\n\n<Trenton, yüzündeki girintili çıkıntılı yara izinde gezdirirken dikkati dağılır.>",
    ["Hey, citizen! You look like a stout one. We guards are spread a little thin out here, and I could use your help..."] = "Hey, vatandaş! Yapılı birine benziyorsun. Buralarda muhafızlar olarak biraz az sayıdayız ve yardımına ihtiyacım var...",
    ["Stormwind is the pillar of the human race, maintained through strength of will and the edge of a sturdy blade."] = "Fırtınayeli, irade gücü ve sağlam bir bıçağın keskinliğiyle ayakta tutulan insan ırkının sütunudur.",
    ["May the Light protect you this day."] = "Işık bugün seni korusun.",
    ["Hey, come over here, and be quiet!"] = "Hey, buraya gel ve sessiz ol!",
    ["Well, now that you mention it, yeah, I did see something I thought was a little strange yesterday afternoon!\n\nI was running past some old troll ruins southeast of here; well, I wasn't really running, more like hopping... The sand's so hot!\n\nAnyway, so I was hopping past the ruins, when I noticed a camp set up there. Seems like a funny place to set up camp, if you ask me... I would have poked around a little more but one of those crazy big vultures chased me off."] = "Şimdi sen söyleyince aklıma geldi, evet, dün öğleden sonra biraz tuhaf olduğunu düşündüğüm bir şey gördüm!\n\nBuranın güneydoğusundaki eski trol harabelerinin yanından koşarak geçiyordum; yani pek koşuyor sayılmazdım, daha çok zıplıyordum... Kumlar o kadar sıcak ki!\n\nHer neyse, harabelerin yanından zıplayarak geçerken orada kurulmuş bir kamp fark ettim. Bana sorarsan kamp kurmak için tuhaf bir yer... Biraz daha etrafa bakınacaktım ama o çılgın büyük akbabalardan biri beni kovaladı.",
    ["De sands be cruel and without compromise. Perfect ground for training."] = "Kumlar zalimdir ve asla taviz vermez. Antrenman yapmak için kusursuz bir zemin.",
    ["With some of the technology that was recovered by bold gnomes venturing into Gnomeregan, I have managed to construct my greatest invention: The Matter Transporter! All I need now is a skilled Gnomish Engineer to build a powerful beacon attuned to the transporter."] = "Gnomeregan'a giren cesur gnomelar tarafından kurtarılan bazı teknolojilerle birlikte, en büyük icatımı inşa etmeyi başardım: Madde Işınlayıcısı! Şimdi tek ihtiyacım olan, ışınlayıcıya uyarlanmış güçlü bir işaret fişeği inşa edecek yetenekli bir Gnome Mühendisi.",
    ["Hi there! I have a proposition for an adventure-seeker such as you, if you are up to the challenge!\n\nAlong with my invention, the Super Egg-O-Matic, I am hard at work aiding the druids with their campaign to save the hippogryphs. The birds are being affected by the evil effects of the Gordunni ogres inhabiting the ruins of Feralas, and their numbers are dwindling.\n\nI collect many different types of eggs. Will you help and find some for me?"] = "Selam! Eğer bu maceraya hazırsan, senin gibi bir macera arayışındakine bir teklifim var!\n\nHarika icadım Süper Yumurtamatik ile birlikte, druidlerin hipogrifleri kurtarma kampanyasına yardım etmek için var gücümle çalışıyorum. Feralas [Feralas] harabelerinde yaşayan Gordunni ogrelerinin kötü etkileri kuşları vuruyor ve sayıları giderek azalıyor.\n\nBirçok farklı türde yumurta topluyorum. Bana yardım edip biraz bulabilir misin?",
    ["You are currently undergoing a hardcore challenge and cannot access guild banks."] = "Şu anda bir zorlu mod [hardcore] mücadelesindesin ve lonca bankalarına [guild bank] erişemezsin.",
    ["In a place called Feralas to the west of here, the hippogryphs, long-time companions of the night elves, are in danger.\n\nI need you to rescue an egg from the ruins of Isildien, to the south, there. The Super Egg-O-Matic can analyze any egg brought to it and judge if it is likely to hatch. I then send the eggs along to the druids, safe from the Gordunni ogres' dark magics.\n\nPlease know, YOUR_NAME, some of the rescued eggs are bad eggs, and will never hatch."] = "Buranın batısında Feralas [Feralas] adında bir yerde, gece elflerinin [night elf] uzun süredir yoldaşı olan hipogrifler tehlikede.\n\nGüneydeki Isildien [Isildien] harabelerinden bir yumurta kurtarmanı istiyorum. Süper Yumurtamatik [Super Egg-O-Matic], kendisine getirilen herhangi bir yumurtayı analiz edebilir ve kuluçkadan çıkma olasılığını değerlendirebilir. Ardından yumurtaları Gordunni ogre'larının [ogre] kara büyülerinden uzak, güvenli bir şekilde druidlere gönderiyorum.\n\nŞunu bil ki YOUR_NAME, kurtarılan yumurtaların bazıları bozuk yumurtalardır ve asla kuluçkadan çıkmayacaklardır.",
    ["I've been working on a way to transport oil underground between major cities, but everyone tells me it's a pipe dream."] = "Büyük şehirler arasında yeraltından petrol taşımanın bir yolu üzerinde çalışıyorum, ancak herkes bunun gerçekleşmesi imkansız bir hayal olduğunu söylüyor.",
    ["Greetings, YOUR_CLASS. I pity your kind, for the secrets of true magic are beyond you..."] = "Selamlar, YOUR_CLASS. Türünüze acıyorum, çünkü gerçek büyünün sırları sizin kavrayışınızın ötesinde...",
    ["May the spirits be with you."] = "Ruhlar seninle olsun.",
    ["You be watchin' yerself, YOUR_CLASS. Respect our ways, or a curse be on you and yours."] = "Kendine dikkat et, YOUR_CLASS. Tarzımıza saygı duy, yoksa lanet senin ve sevdiklerinin üzerine olsun.",
    ["The Valley of Trials will temper even the weakest into a warrior worthy to join the Horde. Those who cannot rise to its tests will be left to bake in the scorching desert sun."] = "İmtihan Vadisi [The Valley of Trials], en zayıfları bile Horde'a katılmaya layık bir savaşçıya dönüştürecektir. Sınavlarının üstesinden gelemeyenler ise kavurucu çöl güneşinde kavrulmaya mahkum edilecektir.",
    ["What kin I do for ya, mon?"] = "Ne yapabilirim senin için, dostum?",
    ["I don't train your kind YOUR_CLASS. Find your own trainer before you anger me."] = "Senin gibileri eğitmiyorum YOUR_CLASS. Beni öfkelendirmeden önce kendi eğitmenini bul.",
    ["What a weird place, mon. I much prefer wall of Zul'Aman to... this.\n\nIf ya be needing training, I be here."] = "Ne tuhaf bir yer, dostum. Zul'Aman surlarını şuraya tercih ederim...\n\nEğer eğitime ihtiyacın olursa, buradayım.",
    ["Your will is not strong enough to manipulate the forces we control, YOUR_CLASS."] = "İradeniz, kontrol ettiğimiz güçleri manipüle etmeye yetmez YOUR_CLASS.",
    ["I have no time to waste on the likes of you YOUR_CLASS."] = "Senin gibilere harcayacak vaktim yok YOUR_CLASS.",
    ["You're no warlock and I've no time for you. Begone!"] = "Sen bir sehhar değilsin ve senin için harcayacak vaktim yok. Defol!",
    ["No other race on Azeroth has suffered as much as our people, YOUR_CLASS. To laugh in the face of death has become second nature for all of us."] = "Azeroth'ta hiçbir diğer ırk halkımız kadar acı çekmedi, YOUR_CLASS. Ölümün yüzüne gülmek hepimiz için ikinci bir doğa haline geldi.",    ["Well met, YOUR_CLASS. My advice to you is this:\nAs you travel the world, be wary of magic for it will burn the untrained."] = "İyi denk geldik, YOUR_CLASS. Sana tavsiyem şudur:\nDünyayı gezerken büyüye karşı dikkatli ol, çünkü eğitimsiz olanları yakar.",
    ["Yes, YOUR_CLASS?"] = "Hayırdır, YOUR_CLASS?",
    ["The path ahead will be different for you, you no longer adapt to nature, nature adapts to you."] = "Önünüzdeki yol sizin için farklı olacak, artık siz doğaya uyum sağlamıyorsunuz, doğa size uyum sağlıyor.",
    ["The howling winds of Tanaris whisper things to me, and I can not speak back... Strange it is to be lost like this."] = "Tanaris'in uluyan rüzgarları bana bir şeyler fısıldıyor, ama ben karşılık veremiyorum... Böyle kaybolmuş olmak ne tuhaf.",
    ["Greetings, YOUR_RACE, the dunes have claimed many a strong adventurer. Walk softly and be careful of the path ahead."] = "Selamlar YOUR_RACE, kum tepeleri nice güçlü maceracıyı yuttu. Sessizce yürü ve önündeki yola dikkat et.",
    ["Greetings, friend! Can I interest you in some ectoplasmic capacitors? Or perhaps a nice omni-directional spectral assimilator?"] = "Selamlar dostum! Seni biraz ektoplazmik kondansatörle ilgilendirebilir miyim? Ya da belki güzel bir omni-direksiyonel spektral asimilatörle?",
    ["Let me break down a little math for you: \"goblin\" plus \"engineering\" equals KNOW HOW, baby. Anyone who tells you otherwise simply doesn't know how to add."] = "Sana biraz matematik anlatayım: \"goblin\" artı \"mühendislik\" eşittir BİRİKİM [know how], bebeğim. Sana aksini söyleyen sadece toplama yapmayı bilmiyordur.",
    ["What can I do for you? No, wait! What can you do for me?"] = "Ne yapabilirim senin için? Hayır, dur! Sen benim için ne yapabilirsin?",
    ["Choose which item you would like to refund."] = "İade etmek istediğiniz eşyayı seçin.",
    ["1. Take the device in both hands.\n\n2. Put it above your head.\n\n3. Let it go.\n\n4. Enjoy the sunshine of the spotless mind.\n\n!!WARNING!! Not spending all specilization points will cause the device to malfunction and reboot! Vizlow will not refund any specialization resets caused by this."] = "1. Cihazı iki elinizle alın.\n\n2. Başınızın üzerine koyun.\n\n3. Bırakın gitsin.\n\n4. Lekesiz zihnin güneş ışığının tadını çıkarın.\n\n!!UYARI!! Tüm uzmanlık puanlarını harcamamak cihazın arızalanmasına ve yeniden başlamasına neden olur! Vizlow, bundan kaynaklanan hiçbir uzmanlık sıfırlamasını iade etmeyecektir.",
    ["What do you need directions to?"] = "Nerenin yol tarifine ihtiyacın var?",
    ["The Call to Arms rings loud in Thorn Gorge. Answer it… or be forgotten like so many before you."] = "Dikenli Geçit [Thorn Gorge]'te Silaha Çağrı yüksek sesle yankılanıyor. Ona yanıt ver... ya da senden önceki pek çokları gibi unutulup git.",
    ["Hello, YOUR_NAME! I am master engineer, Scooty."] = "Merhaba, YOUR_NAME! Ben usta mühendis Scooty'yim.",
    ["Welcome to the Shell Co. Trading Company!\n\nI'm a genius! I have invented a brand new currency which will take Azeroth by storm! The magical Shellcoin will forever change the way we exchange goods, with every coin being unique a irreplaceable.\n\nDown on your luck? Now is the time to invest in Shellcoin! Watch the market and hit it big!"] = "Shell Co. Ticaret Şirketi'ne hoş geldiniz!\n\nBen bir dahiyim! Azeroth'u kasıp kavuracak yepyeni bir para birimi icat ettim! Büyülü Shellcoin, her sikkenin benzersiz ve yeri doldurulamaz olmasıyla mal değişim şeklimizi sonsuza dek değiştirecek.\n\nİşleriniz kötü mü gidiyor? Shellcoin'e yatırım yapmanın tam zamanı! Piyasayı takip edin ve büyük vurgunu yapın!",
    ["I can teach you fishing skills."] = "Sana balıkçılık becerileri öğretebilirim.",
    ["Greetings YOUR_NAME"] = "Selamlar YOUR_NAME",
    ["I must say, Booty Bay has the best Clam Chowder to be had anywhere in the South Seas. Oh, not interested in cuisine eh? Well then let me be the first to welcome you to the berth of the Maiden's Fancy, the finest passenger ship to travel between the Eastern Kingdoms and Kalimdor. She's due back for another trip to Ratchet soon, so make yourself comfortable till she arrives."] = "Şunu söylemeliyim ki Ganimet Koyu [Booty Bay], Güney Denizleri'nde bulabileceğiniz en iyi midye çorbasına sahip. Ah, mutfakla ilgilenmiyorsun galiba? Öyleyse Doğu Krallıkları [Eastern Kingdoms] ile Kalimdor arasında seyahat eden en iyi yolcu gemisi Maiden's Fancy'nin rıhtımına hoş geldin diyen ilk kişi olayım. Cüce [Ratchet] için yakında tekrar yola çıkacak, bu yüzden o gelene kadar rahatına bak.",
    ["All these boxes and cargo laying around, we need to make some adjustments around here."] = "Ortalıkta duran tüm bu kutular ve kargolar, burada bazı düzenlemeler yapmamız gerekiyor.",
    ["Time is money, friend, and my time is very valuable.\n\nGivin' we both have better things to be doing, how about you tell me what business you have here? Keep your eyes off the coinage. Understand?"] = "Zaman paradır dostum ve benim zamanım çok değerli.\n\nİkimizin de yapacak daha iyi işleri olduğuna göre, neden burada ne işin olduğunu bana anlatmıyorsun? Gözlerini sikkelerden uzak tut. Anladın mı?",
    ["I see some interesting characters come and go here at the port. Watch yourself, YOUR_NAME. It's never clear who to trust, what with all of the shady activity that goes on here..."] = "Limanda gelip giden ilginç karakterler görüyorum. Kendine dikkat et YOUR_NAME. Burada dönen onca karanlık işten sonra kime güveneceğin asla belli olmaz...",
    ["I made a lot of the things you see in the store. What do you think? Answer carefully, your life may depend on it."] = "Mağazada gördüğün şeylerin çoğunu ben yaptım. Ne düşünüyorsun? Dikkatli cevap ver, hayatın buna bağlı olabilir.",
    ["Ahoy matey, I am very curious to see what new chapter for the Bloodsail Buccaneers you will be painting. I will be watching the Cap'n's lodge for a while but when ye come here to rest or spend some alone time I will be gone."] = "Selam dostum, Kanlıyel Korsanları [Bloodsail Buccaneers] için hangi yeni sayfayı boyayacağını görmek için çok meraklıyım. Bir süre Kaptan'ın kulübesini gözleyeceğim ama buraya dinlenmeye veya yalnız vakit geçirmeye geldiğinde gitmiş olacağım.",
    ["Welcome to my shop, warrior. What is it the Goodstitch brothers can do for you?"] = "Dükkanıma hoş geldin savaşçı. İyi Dikiş [Goodstitch] kardeşler senin için ne yapabilir?",
    ["Come in, come in. Just don't sit too close to the stove. It hasn't exploded yet today, but just to be safe I think you should sit elsewhere."] = "İçeri gel, içeri gel. Sadece sobanın çok yakınına oturma. Bugün henüz patlamadı ama yine de garantiye almak için başka bir yere oturmalısın.",
    ["Welcome to the Pig and Whistle! Grab a drink my friend and pull up a seat, the more the merrier!"] = "Domuz ve Ddüdük [Pig and Whistle]'e hoş geldiniz! Bir içki kap dostum ve kendine bir sandalye çek, ne kadar çok o kadar neşe!",
    ["The ambitions and desires of Kul Tiras are a complicated matter. Our goal here is to determine the true value of these southerners and to see if mainlanders can be trusted.\n\nShould the nobility of Stormwind prove themselves loyal to the old ways and old causes, then perhaps there may be a future of cooperation.\n\nWe shall see where the heart of Stormwind is rightly at."] = "Kul Tiras'ın tutkuları ve arzuları karmaşık bir meseldir. Buradaki amacımız bu güneylilerin gerçek değerini belirlemek ve anakaralılara güvenilip güvenilemeyeceğini görmektir.\n\nEğer Fırtınayeli [Stormwind] soyluluğu kendilerini eski yollara ve eski davalara sadık kanıtlarsa, o zaman belki bir işbirliği geleceği olabilir.\n\nFırtınayeli [Stormwind]'in kalbinin gerçekten nerede olduğunu göreceğiz.",
    ["Can I help you?"] = "Size yardım edebilir miyim?",
    ["Welcome to Booty Bay, partner. I hope your stay in my town is enjoyable and uneventful - emphasis on the latter. We've got plenty of drink if you're thirsty, and plenty of bouncers if you're antsy.\n\nNow then... what can this humble servant of the Steamwheedle Cartel do for you? Better still - what can you do for me, eh?"] = "Ganimet Koyu [Booty Bay]'ne hoş geldin ortak. Kasabamda geçirdiğin sürenin keyifli ve olaylarız geçmesini umuyorum - özellikle de ikincisini vurguluyorum. Eğer susadıysan bolca içeceğimiz, huzursuzsan bolca fedaimiz var.\n\nŞimdi bakalım... Buharkesen Karteli [Steamwheedle Cartel]'nin bu mütevazı hizmetkarı senin için ne yapabilir? Daha da iyisi - sen benim için ne yapabilirsin, ha?",
    ["These great beasts know paths that ye can't find on foot, they'll get ye there fast and maybe show ye something new at the same time."] = "Bu büyük canavarlar yaya olarak bulamayacağın yolları bilir, seni oraya hızlıca ulaştırır ve belki de aynı anda sana yeni bir şeyler gösterirler.",
    ["I already know a lot about style. Now it's just a matter of mastering the techniques for working with leather. Good thing Simon's a real sport about helping me learn them."] = "Tarz hakkında zaten çok şey biliyorum. Artık mesele derizle çalışma tekniklerinde ustalaşmaktan ibaret. Simo'nun bunları öğrenmeme yardım etme konusunda gerçek bir sporcu ruhu sergilemesi harika bir şey.",
    ["Greetings and salutations, hero! I have the latest news from both continents and points beyond for your consideration."] = "Selamlar ve saygılar, kahraman! İncelemeniz için her iki kıtadan ve ötesindeki noktalardan en son haberlere sahibim.",
    ["What is it you want? I'm busy, so move it along."] = "Ne istiyorsun? Meşgulüm, o yüzden çabuk ol.",
    ["I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin."] = "Yalnızca test edilmiş ve güvenilir en iyi teçhizatı satarım. Fiyatlar da sabittir, yani pazarlık etmek istiyorsan git bir Goblin bul.",
    ["Where would you like to fly to?"] = "Nereye uçmak istersiniz?",
    ["Pssst... I can make you hide who you really are with some fake papers if you bring me 5 gold."] = "Psst... Bana 5 altın getirirsen sahte evraklarla gerçekten kim olduğunu gizlemeni sağlayabilirim.",
    ["Watch your step in here, boy. The master sees all..."] = "Burada adını attığına dikkat et evlat. Efendi her şeyi görür...",
    ["Speak quietly and with great care, the wrong word in these parts could get your throat cut. Now, what is it you need from me?"] = "Alçak sesle ve büyük bir özenle konuş, bu buralarda yanlış bir kelime boğazının kesilmesine neden olabilir. Şimdi, benden neye ihtiyacın var?",
    ["Welcome to SI:7 headquarters, YOUR_NAME."] = "SI:7 karargahına hoş geldin, YOUR_NAME.",
    ["I don't think you want to learn anything I can teach. Might want to find a warrior trainer to help you out."] = "Öretebileceğim herhangi bir şeyi öğrenmek isteyeceğini sanmıyorum. Sana yardım etmesi için bir savaşçı eğitmeni bulmak isteyebilirsin.",
    ["Randal's a bit of a dandy, but he's dependable, which is more than I can say for a lot of the students I take on. Still, I guess I can't blame them for wanting a bit of adventure."] = "Randal biraz züppedir ama güvenilirdir, ki bu aldığım öğrencilerin birçoğu için söyleyebileceğimden fazlasıdır. Yine de sanırım biraz macera istemeleri konusunda onları suçlayamam.",
    ["The war against the Horde has reached full tilt, YOUR_NAME. This is a time of great need for the Alliance and it's quite necessary that all of us do our part to help."] = "Sürü [Horde] ile olan savaş son hızına ulaştı, YOUR_NAME. Bu İttifak [Alliance] için büyük bir ihtiyaç zamanı ve hepimizin yardım etmek için üzerimize düşeni yapması oldukça gerekli.",
    ["<Lady Prestor glares at you.>"] = "<Leydi Prestor sana sertçe bakıyor.>",
    ["I have come here to seek support of the Nobles of Stormwind. It is a harder task than I had anticipated."] = "Fırtınayeli [Stormwind] Soylularının desteğini istemek için buraya geldim. Beklediğimden daha zor bir görev.",
    ["I've been expecting you YOUR_NAME.  Are you ready to assist us in Arathi Basin?"] = "Seni bekliyordum YOUR_NAME. Arathi Havzası [Arathi Basin]'nda bize yardım etmeye hazır mısın?",
    ["I am sorry YOUR_CLASS, but you need to be more experienced before you can survive in Alterac Valley."] = "Üzgünüm savaşçı, ancak Alterac Vadisi [Alterac Valley]'nde hayatta kalabilmek için daha tecrübeli olman gerekiyor.",
    ["Hail to thee YOUR_NAME.  Do you wish me to aid you in your journey to Warsong Gulch?"] = "Selam olsun sana YOUR_NAME. Savaşşarkısı Uçurumu [Warsong Gulch] yolculuğunda sana yardım etmemi ister misin?",
    ["This may not be very obvious at first glance, Human, however, I assure you, we are glad to accept the help the Alliance is giving us in such dire times."] = "Bu ilk bakışta çok açık olmayabilir insan, ancak sana garanti ederim ki, İttifak [Alliance]'ın böyle zor zamanlarda bize verdiği yardımı kabul etmekten memnuniyet duyuyoruz.",
    ["Anduin might be just a boy now, but he will be a great leader one day. His heart is pure and filled with light. With his father missing, it falls to me to tutor him and rule the kingdom until he is of age."] = "Anduin şu an sadece bir çocuk olabilir ama bir gün büyük bir lider olacak. Kalbi saf ve ışıkla dolu. Babası kayıpken, ona öğretmenlik yapmak ve o reşit olana kadar krallığı yönetmek bana düşüyor.",
    ["The Bael Modan Garrison requires aid in their mission to gather ground in the western frontier of Kalimdor! Are you willing to step up and defend the Alliance's interests?"] = "Bael Modan Garnizonu, Kalimdor'un batı sınırında zemin kazanma görevlerinde yardıma ihtiyaç duyuyor! İttifak [Alliance]'ın çıkarlarını savunmak için öne çıkmaya istekli misin?",
    ["Once I find the right buyer, I will strike big and bathe in heaps of gold!"] = "Doğru alıcıyı bulduğumda, büyük bir vurgun yapıp altın yığınları içinde yıkanacağım!",
    ["I scoff at your empty threats. What do you intend to do, kill me? Here, out in the open? Even a lowly agent of Ravenholdt wouldn’t stoop to such levels of unprofessionalism. You have nothing on me."] = "Boş tehditlerini alaya alıyorum. Ne yapmayı düşünüyorsun, beni öldürmek mi? Burada, ortalık yerde mi? Ravenholdt'un sıradan bir ajanı bile profesyonellikten bu kadar yoksun seviyelere düşmez. Elimde bana karşı hiçbir şey yok.",
    ["You'll have to be patient with me, YOUR_NAME. I've got my Spybot inside working on a very delicate matter. I'll be with ya in a second.\n\nOh, and do me a favor, try not to let Lescovar see you... we're about to ambush him."] = "Benimle sabırlı olman gerekecek, YOUR_NAME. İçeride çok hassas bir meseleyle uğraşan Casusbot'um [Spybot] var. Bir saniyeye seninle olacağım.\n\nAh, ve bana bir iyilik yap, Lescovar'ın seni görmesine izin vermemeye çalış... ona pusu kurmak üzereyiz.",
    ["Ey mon, you be looking like you could use a few trinkets, let Vil'do tell you what you be needing."] = "Ey dostum, birkaç zımbırtıya ihtiyacın varmış gibi görünüyorsun, neye ihtiyacın olduğunu Vil'do'nun söylemesine izin ver.",
    ["You wouldn't happen to have a few coin on you, huh? I need it for the next time we stop somewhere."] = "Üstünde birkaç sikke falan yoktur, değil mi? Bir yerlerde bir sonraki duruşumuz için buna ihtiyacım var.",
    ["I will never care of your rank, I respect strength above else. Prove yourself to be worthy of my axe and I will die for you. Do not mistake these words for mutiny, I will respect your orders and will not question them."] = "Rütbeni asla umursamayacağım, her şeyin üstünde güce saygı duyarım. Baltama layık olduğunu kanıtla ve senin için öleyim. Bu sözleri isyan olarak karıştırma, emirlerine saygı duyacağım ve onları sorgulamayacağım.",
    ["Heya, sweetie. Here to make a long time investement?\n\nMaybe you wanna gamble, little YOUR_CLASS? Tell me how much and I'll throw the dice. If the roll is above 50, I will double the bet. If it's lower than 50, it's gone forever.\n\nIf you win three times in a row using the same amount, the reward is tripled, but only if the 3rd roll is above 75. If it's below 75 on the 3rd roll, your gold will be gone too."] = "Selam tatlım. Uzun vadeli bir yatırım yapmaya mı geldin?\n\nBelki kumar oynamak istersin, küçük YOUR_CLASS? Ne kadar olduğunu söyle ve zarları atayım. Eğer atılan sayı 50'nin üzerindeyse, bahsi iki katına çıkaracağım. 50'den düşükse, sonsuza dek gider.\n\nAynı miktarı kullanarak arka arkaya üç kez kazanırsan, ödül üç katına çıkarılır, ancak yalnızca 3. zar 75'in üzerindeyse. 3. zarda 75'in altındaysa, altınların da gidecektir.",
    ["Welcome aboard, we Bloodsail treat eachother well at the least, if you remain loyal."] = "Gemiye hoş geldin, biz Kanlıyel [Bloodsail] korsanları sadık kalırsan en azından birbirimize iyi davranırız.",
    ["Just because I'm old don't think I'm weak, ye understand young one? Ye let yer guard down for but a moment and Old-Tide Sam will pull you under."] = "Yaşlıyım diye zayıf olduğumu sanma, anlıyor musun genç adam? Dikkatini sadece bir anlığına bile dağıtırsan, Yaşlı-Dalga Sam seni dibe çeker.",
    ["No better place to rest up then on the ship! The rocking of the waves is almost gentle don't you agree?"] = "Dinlenmek için gemiden daha iyi bir yer olamaz! Dalgaların sallantısı neredeyse nazik, değil mi?",
    ["You're going to scare off all the fish!"] = "Bütün balıkları kaçıracaksın!",
    ["They're going to show fireworks all long. From 6PM until dawn, the sky will blaze over Booty Bay!"] = "Bütün gece boyunca havai fişek gösterisi yapacaklar. Akşam 6'dan şafağa kadar gökyüzü Ganimet Koyu [Booty Bay] üzerinde parıl parıl parlayacak!",
    ["You look familiar, you one of the new crew members?"] = "Tanıdık görünüyorsun, yeni mürettebat üyelerinden biri misin?",
    ["Another Bloodsail huh? Not often someone wanders around out here and just shows up, what you looking to help?"] = "Bir başka Kanlıyel [Bloodsail] ha? Sık sık buralarda dolaşıp öylece ortaya çıkan biri olmaz, neye yardım etmek istiyorsun?",
    ["Welcome, listener! On behalf of BootyBay Pirate Radio, I am here to gather the public opinion on all sorts of matters. Every opinion counts, and individual votes are kept anonymous. Different polls will have different requirements to vote."] = "Hoş geldin, dinleyici! Ganimet Koyu [BootyBay] Korsan Radyosu adına, her türlü konudaki kamuoyunu toplamak için buradayım. Her görüş önemlidir ve bireysel oylar gizli tutulur. Farklı anketlerin oy kullanmak için farklı gereksinimleri olacaktır.",
    ["We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world.\n\nThe leader of our expedition, Molthor, brought us to the Yojamba Isle, along the northern coasts of Stranglethorn, and even now recruits brave heroes to venture into the ancient troll city... Zul'Gurub."] = "Biz Zandalari trolleri, uzak adalardan buraya seyahat ettik, çünkü dünyamızın karşısına çıkan tehdidi görmezden gelemeyiz.\n\nKeşif gezimizin lideri Molthor, bizi Stranglethorn'un kuzey kıyısı boyunca Yojamba Adası [Yojamba Isle]'na getirdi ve şu anda bile antik troll şehri... Zul'Gurub'a maceraya atılmaları için cesur kahramanları topluyor.",
    ["Why hello there, you wouldn't mind helping out a dwarf in need would ye?"] = "Merhaba orada, muhtaç bir cüceye yardım etmekten sakınmazsın değil mi?",
    ["Hey there, I'm Wincing Willy Pal! Heard good things about you, the only reason we're talking right now. My job is to oversee supplies coming from the great seas and keep them here until we can allocate them elsewhere."] = "Selam, ben Yüzü Ekşiten Willy Dost! Hakkında iyi şeyler duydum, şu anda konuşmamızın tek sebebi de bu. Benim işim büyük denizlerden gelen ikmalleri denetlemek ve onları başka bir yere tahsis edene kadar burada tutmak.",
    ["What do you want, Maggot?"] = "Ne istiyorsun, Kurtçuk?",
    ["Cross-faction battlegrounds\n\nDo you support cross faction BGs?"] = "Irklar arası savaş alanları [Cross-faction battlegrounds]\n\nIrklar arası BGs (Savaş Alanları) özelliğini destekliyor musunuz?",
    ["Thank you for the offer, YOUR_CLASS. Unfortunately you are not yet experienced enough to weather the hazards of Arathi Basin."] = "Teklifin için teşekkürler YOUR_CLASS. Ne yazık ki Arathi Havzası [Arathi Basin]'nın tehlikelerine göğüs gerecek kadar henüz deneyimli değilsin.",
    ["Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?"] = "Fırtınaşehri [Stormwind]'ndeki en iyi fırsatlar bende dostum, daha iyisini bulamazsın. Şimdi, sana nasıl yardımcı olabilirim?",
    ["You have journeyed a great distance. Rest your weary body under our roof, and may the Sun guide you."] = "Çok uzak yoldan geldin. Yorgun bedenini çatımız altında dinlendir; Güneş sana yol göstersin.",
    ["Who would have thought combining the usefulness of a telescope with a mining pick would be such a hit! I'm sure a fine YOUR_RACE like you can see the appeal!\n\nIf you want one yourself, bring me an Ornate Spyglass and some Light Leather, let's say around... 10 pieces."] = "Bir teleskobun kullanışlılığını bir madenci kazmasıyla birleştirmenin bu kadar tutacağını kim düşünebilirdi ki! Senin gibi nezih bir YOUR_RACE bunun cazibesini görebildiğinden eminim!\n\nKendine bir tane istersen, bana bir Süslü Dürbün [Ornate Spyglass] ve biraz Hafif Deri [Light Leather] getir, diyelim ki... 10 parça kadar.",
    ["Thank you for the offer, warrior. Unfortunately you are not yet experienced enough to weather the hazards of Arathi Basin."] = "Teklifin için teşekkürler savaşçı. Ne yazık ki Arathi Havzası [Arathi Basin]'nın tehlikelerine göğüs gerecek kadar henüz deneyimli değilsin.",
    ["Will you help us in our time of great need at Arathi Basin, warrior? The chance for increased honor and standing is greater than ever, and your assistance is sure to help to turn the tide against The Defilers. Can we count on you?"] = "Arathi Havzası [Arathi Basin]'ndaki bu büyük ihtiyaç anımızda bize yardım edecek misin savaşçı? Daha fazla onur ve itibar kazanma şansı her zamankinden daha yüksek ve yardımının Kirleticiler [The Defilers]'e karşı gidişatı değiştireceğinden eminiz. Sana güvenebilir miyiz?",
    ["See, the Venture Company's new shredder is better than my latest, from the interchangeable hands to the control grips!\n\nMy boss has given me a pretty strict deadline, but my boys and I couldn't come up with anything. Nothing was working, so we decided to \"borrow\" one of their prototypes. I sent Wizzlecrank to the Sludge Fen to steal one, but he hasn't gotten back yet!"] = "Baksana, Girişim Şirketi [Venture Company]'nin yeni öğütücüsü [shredder], değiştirilebilir ellerinden kontrol kollarına kadar benim son yaptığımdan çok daha iyi!\n\nPatronum bana oldukça katı bir teslim tarihi verdi ama çocuklar ve ben ortaya hiçbir şey çıkaramadık. Hiçbir şey işe yaramayınca biz de onların prototiplerinden birini \"ödünç almaya\" karar verdik. Bir tane çalması için Wizzlecrank'i Çamur Bataklığı [Sludge Fen]'na gönderdim ama henüz geri dönmedi!",
    ["These are bleak times, but our kin must be guided towards the Light. Their wounds, while they cannot be healed entirely, must be attended to with all our might."] = "Karanlık zamanlardan geçiyoruz, ancak soydaşlarımız Işık'a [Light] doğru yönlendirilmelidir. Yaraları tamamen iyileştirilemese de var gücümüzle ilgilenilmelidir.",
    ["Director Riddlevox put me in charge of the Union's shredder development program. Few months on the job and I'm already in hot water! I could use your help, YOUR_NAME!"] = "Müdür Riddlevox beni Birlik [Union]'in öğütücü [shredder] geliştirme programının başına geçirdi. İşteki daha birkaç ayımda başım derde girdi bile! Yardımına ihtiyacım var, YOUR_NAME!",
    ["Ever since the Sunwell fell, we've strained to minimize the amount of mana we expend. We used to be paragons of arcane power; now, we are a mere shadow of our former selves."] = "Güneşpınarı [Sunwell] düştüğünden beri harcadığımız mana miktarını en aza indirmek için çabalıyoruz. Eskiden arkana gücünün timsaliydik; şimdi ise eski halimizin sadece bir gölgesiyiz.",
    ["The Farstriders were a proud group of rangers, with the fall of our land they too have been left behind, yet it is in us that their legacy will live on."] = "Uzakgezginler [Farstriders] gururlu bir korucu grubuydu; topraklarımızın düşüşüyle onlar da geride kaldılar, ancak onların mirası bizim içimizde yaşamaya devam edecek.",
    ["Hello there, what can I do for you?"] = "Merhaba, senin için ne yapabilirim?",
    ["Yes. A caravan with men and women dressed in scarlet passed through here. Many of our young ones followed them."] = "Evet. Buradan al kıyafetler giymiş kadın ve erkeklerden oluşan bir kervan geçti. Gençlerimizin çoğu onları takip etti.",
    ["Help!\n\nIf you get me out of here, I can blow up the door that leads to the chief of Zul'Farrak!"] = "İmdat!\n\nBeni buradan çıkarırsan, Zul'Farrak şefine çıkan kapıyı havaya uçurabilirim!",
    ["Rough times, huh, Waya? No matter where you turn someone needs help, and my wife and I are no exception."] = "Zor zamanlar, değil mi Waya? Nereye dönsen birinin yardıma ihtiyacı var, karım ve ben de buna bir istisna değiliz.",
    ["Help! My band and I have been captured by trolls, and they're going to sacrifice us!\n\nGet us out of here and I'll give you anything you want."] = "İmdat! Grubum ve ben troller tarafından yakalandık ve bizi kurban edecekler!\n\nBizi buradan çıkar, sana ne istersen vereceğim.",
    ["What brings you to the Tower of Azora? Is it a search for knowledge, or the greater arcane?\n\nWhatever it may be, I am sure we can be of assistance."] = "Seni Azora Kulesi [Tower of Azora]'ne getiren nedir? Bilgi arayışı mı, yoksa daha büyük gizemli güç [arcane] mi?\n\nHer ne olursa olsun, yardımcı olabileceğimizden eminim.",
    ["I'm sorry, I'm a bit busy right now making horseshoes for Verner Osgood in Lakeshire. "] = "Üzgünüm, şu anda Gölkesimi [Lakeshire]'ndeki Verner Osgood için at nalı yapmakla biraz meşgulüm.",
    ["Do not be alarmed, YOUR_RACE. I have long since passed from this land but I intend no harm to your kind. I have witnessed too much death in my time. My only wish now is for peace. Perhaps you can help my cause."] = "Paniğe kapılma, insan. Ben bu diyardan göçeli çok oldu ama soyunuza zarar verme niyetinde değilim. Zamanımda çok fazla ölüme tanık oldum. Şu anki tek dileğim barış. Belki davama yardımcı olabilirsin.",
    ["Hello there mister... do you have a little time that you could help us out? Please?"] = "Merhaba bayım... bize yardım edebilecek biraz vaktiniz var mı? Lütfen?",
    ["Where are you going? Well if you're looking to get there quickly, then look no further!"] = "Nereye gidiyorsun? Eğer oraya hızlıca ulaşmak istiyorsan, doğru yerdesin!",
    ["I can teach you the finer points of Horse Riding, provided you have enough gold to cover the lesson!"] = "Dersi karşılamaya yetecek kadar altının varsa, sana At Biniciliğinin inceliklerini öğretebilirim!",
    ["The desert be rife with opportunities, and chances to gain a little coin. I represent some interests across the ocean that are looking for rare and unique goods.\n\nPerhaps we can help each other out, aye?\n\nOh, and uh, if you're looking for some cheddar, I got a bunch of it, they took my letter way too seriously."] = "Çöl, fırsatlarla ve biraz sikke kazanma şansıyla doludur. Okyanusun ötesinde nadir ve benzersiz mallar arayan bazı kişilerin çıkarlarını temsil ediyorum.\n\nBelki birbirimize yardım edebiliriz, ha?\n\nAh, ve eğer biraz çedar peyniri arıyorsan bende bolca var, mektubumu fazla ciddiye aldılar.",
    ["I can tell just by the way you're standing that you're no warrior. \n\nWhy don't you go do something safe, like read a book."] = "Sadece duruşundan bile bir savaşçı olmadığını anlayabiliyorum.\n\nNeden gidip kitap okumak gibi güvenli bir şeyler yapmıyorsun.",
    ["This is a dangerous place, Waya. Be careful around here."] = "Burası tehlikeli bir yer, Waya. Buralarda dikkatli ol.",
    ["Take a look upon my wares. I am the best tailor in this lightforsaken town."] = "Mallarıma bir göz at. Işıktan terk edilmiş bu kasabadaki en iyi terzi benim.",
    ["I don't suppose you're here for a mere chit-chat. Take a rest, spend your coins and leave me be, mortal."] = "Sadece laflamak için burada olduğunu sanmıyorum. Dinlen, sikkelerini harca ve beni yalnız bırak, fani.",
    ["What are you looking for?"] = "Ne arıyorsun?",
    ["I don't have much time for idle talk, Waya.  I've got to get this bridge rebuilt before the rains come.  I've finished every project on-time and under budget and I'm not about to start slipping now."] = "Boş konuşmalar için pek vaktim yok, Waya. Yağmurlar gelmeden önce bu köprüyü yeniden inşa etmem gerekiyor. Her projeyi zamanında ve bütçenin altında bitirdim, şimdi aksatmaya başlayacak değilim.",
    ["I think my necklace fell in the lake.  My daddy got it for me, and he's gonna be mad now."] = "Sanırım kolyem göle düştü. Babam onu benim için almıştı, şimdi çok kızacak.",
    ["Are you looking to gain standing with the Wardens, mortal? Are you looking to keep harmony within the strands of time?\n\nLook no further then here, each day we remain idle is another day that chaos begins to tear apart order.\n\nThe forces that seek to undermine our work will not stop. There is always more that can be done, and you are here for that very reason, are you not?"] = "Muhafızlar [Wardens] nezdinde itibar kazanmak mı istiyorsun fani? Zamanın akışında uyumu korumak mı istiyorsun?\n\nAradığın yer tam da burası; boş durduğumuz her gün, kaosun düzeni parçalamaya başladığı başka bir gündür.\n\nİşimizi baltalamaya çalışan güçler durmayacak. Her zaman yapılabilecek daha fazla şey vardır ve sen de tam olarak bu yüzden buradasın, değil mi?",
    ["Who is this warrior who goes before the Court of Lakeshire in the Kingdom of Stormwind?  State your business within this township, Human.  The orc threat to the Kingdom is far too great to squander time in idle conversation."] = "Fırtınayeli Krallığı [Kingdom of Stormwind]'ndaki Gölkesimi Mahkemesi [Court of Lakeshire]'nin huzuruna çıkan bu savaşçı da kim? Bu kasabadaki işini beyan et, İnsan. Krallık üzerindeki ork tehdidi, boş sohbetlerle vakit harcanamayacak kadar büyük.",
    ["Don't come out of the shadows like that. Next time give a girl some warning. "] = "Gölgelerden öyle aniden çıkma. Bir dahakine bir kadına önceden haber ver.",
    ["I try to keep Sentinel Hill stocked, and that's not easy with all the action we see."] = "Gözcü Tepesi [Sentinel Hill]'ni erzaklı tutmaya çalışıyorum ve gördüğümüz tüm bu hareketlilik içinde bu hiç de kolay değil.",
    ["I can tell that your wardrobe is in dire need of care."] = "Gardırobunun bakıma çok ihtiyacı olduğunu görebiliyorum.",
    ["Welcome, looking to get some premium wares?"] = "Hoş geldin, birinci sınıf mallar mı almak istiyorsun?",
    ["Welcome to my Inn, weary traveler. What can I do for you?"] = "Hanıma hoş geldin, yorgun yolcu. Senin için ne yapabilirim?",
    ["The shores have been growing more concerning as of late, let us pray that things will not escalate further."] = "Kıyılar son zamanlarda daha endişe verici hale geliyor, dua edelim de işler daha da tırmanmasın.",
    ["The times are tough, but there's always opportunity for business."] = "Zamanlar zor ama ticaret için her zaman bir fırsat vardır.",
    ["Greetings, warrior. Though time and drink have dulled my outer senses, my inner eyes remain strong."] = "Selamlar savaşçı. Zaman ve içki dış duyularımı köreltmiş olsa da, iç gözlerim güçlü kalmaya devam ediyor.",
    ["What is it, mortal? Inside? Yes, you may. I believe you still hold an ability to see that there is nothing that blocks your way in. Correct?"] = "Ne var, fani? İçerisi mi? Evet, girebilirsin. İçeri girmene engel olan hiçbir şey olmadığını görebilme yeteneğine hâlâ sahip olduğuna inanıyorum. Doğru mu?",
    ["The path to the caverns is long arduous. Mayhap I can ease your burdens and take you deeper in the Cavern."] = "Mağaralara giden yol uzun ve meşakkatli. Belki yükünü hafifletip seni Mağara'nın daha derinlerine götürebilirim.",
    ["Years of quality breeding techniques and plenty of care allow me the privilege of showing you these horses! Please, take your time as you consider them for your mount. A horse is a companion for the ages, friend. Don't sell yourself short - get your steed here today!"] = "Yılların kaliteli yetiştirme teknikleri ve bolca bakım, bana bu atları sana gösterme ayrıcalığını veriyor! Bineğin olarak değerlendirirken lütfen acele etme. Bir at çağlar boyu bir arkadaştır dostum. Kendini ucuza çıkarma - binek atını bugün buradan al!",
    ["It has been a long time since a mortal has walked these halls. As much as I have my distaste for you all, I understand that we require your aid."] = "Bir faninin bu salonlarda yürümesinden bu yana uzun zaman geçti. Hepinizden ne kadar tiksensem de, yardımınıza ihtiyacımız olduğunu anlıyorum.",
    ["<Razjal gives you a hostile gaze.>"] = "<Razjal sana düşmanca bir bakış atıyor.>",

            
}

QuestTranslator_OptionData = {
    ["Seen any strange things in the desert lately?"] = "Son zamanlarda çölde garip bir şeyler gördün mü?",
    ["Please tell me more about the Gordunni ogres."] = "Lütfen bana Gordunni ogre'ları [ogre] hakkında daha fazla bilgi ver.",
    ["Please tell me more about the hippogryphs."] = "Lütfen bana hipogrifler hakkında daha fazla bilgi ver.",
    ["I'm not interested, goodbye."] = "İlgilenmiyorum, hoşçakal.",
    ["Yes... I want some privacy, can you hide my rank? I'll give you the gold.\n\nWARNING: THIS WILL COST YOU 5 GOLD!"] = "Evet... Biraz mahremiyet istiyorum, rütbemi gizleyebilir misin? Altını vereceğim.\n\nUYARI: BU SİZE 5 ALTINA MAL OLACAK!",
    ["Your schemes aren’t going anywhere. I’m here to collect the information."] = "Planlarınız hiçbir yere varamayacak. Bilgileri toplamaya geldim.",
    ["I'll call it The Crying Dandelion."] = "Adını Ağlayan Karahindiba koyacağım.",    
    ["That eyepatch is coming with me."] = "O göz bandı benimle geliyor.",
    ["Poison the rum."] = "Romu zehirle.",
    ["Spit in Morgan's face."] = "Morgan'ın yüzüne tükür.",
    ["ALREADY VOTED - Cross-faction battlegrounds"] = "OY KULLANILDI - Irklar arası [Cross-faction] Savaş Alanları",
    ["[Close]"]="[Kapat]",
    ["How can I help?"]="Nasıl yardımcı olabilirim?",
    ["Please, install the telescopic lens!"] = "Lütfen teleskopik merceği takın!",
    ["Show me where I can fly."] = "Nereye uçabileceğimi göster.",
